"""Media transforms. All working filenames are generated by us under a temp directory."""
import hashlib
import json
import re
import subprocess
from math import isfinite

from music_screen import audio_activity, decode_audio

# Allow for 30 fps frame rounding and AAC packet padding in the MP4 container.
MIN_SEGMENT_SECONDS = 18
MAX_SEGMENT_SECONDS = 43.9


def run(cmd, cwd):
    subprocess.run(cmd, cwd=cwd, check=True, stdin=subprocess.DEVNULL)


def probe(path):
    cmd = ["ffprobe", "-v", "error", "-of", "json", "-show_streams", "-show_format", str(path)]
    return json.loads(subprocess.check_output(cmd))


def seconds(path):
    return float(probe(path)["format"]["duration"])


def analyze_audio(path, length):
    return audio_activity(decode_audio(path, min(length, 46)))


def safe(text):
    # Prevent source text from becoming an ASS override, newline, or positioning command.
    return " ".join(str(text).translate(str.maketrans({"\\": "／", "{": "(", "}": ")"})).split())


def stamp(t):
    cs = max(0, round(t * 100))
    return f"{cs // 360000}:{cs // 6000 % 60:02}:{cs // 100 % 60:02}.{cs % 100:02}"


def valid_word(item):
    if not isinstance(item, (list, tuple)) or len(item) != 3:
        return False
    start, end, word = item
    return (isinstance(word, str) and bool(word.strip())
            and all(isinstance(t, (int, float)) and isfinite(t) for t in (start, end))
            and end > start)


def curiosity_hook(title, override=None):
    if isinstance(override, str):
        cleaned = safe(override)
        if len(cleaned) <= 68 and 3 <= len(cleaned.split()) <= 5 and all(
                any(c.isalnum() for c in word) for word in cleaned.split()):
            return cleaned
    tokens = re.findall(r"[A-Za-z0-9']+", title.casefold() if isinstance(title, str) else "")
    themes = (
        ({"chase", "cops", "police", "getaway", "escape"}, "CAN THEY GET AWAY?"),
        ({"jump", "ramp", "stunt", "landing"}, "CAN THEY LAND THIS?"),
        ({"drift", "corner", "turn"}, "WATCH THAT LAST TURN"),
        ({"heist", "vault", "robbery"}, "WILL THE PLAN WORK?"),
        ({"chat", "reaction", "reacts"}, "WHAT SET CHAT OFF?"),
        ({"race", "finish", "overtake"}, "WHO TAKES THE LEAD?"),
        ({"crash", "crashes", "pileup"}, "WHAT CAUSED THE CRASH?"),
    )
    for keywords, hook in themes:
        if keywords.intersection(tokens):
            return hook
    if isinstance(title, str) and len(title.strip()) <= 68 and title.strip().endswith("?") and 3 <= len(tokens) <= 5:
        return " ".join(tokens).upper() + "?"
    hooks = ("DID YOU CATCH THAT?", "WHAT HAPPENS NEXT?", "WATCH THIS PART CLOSELY")
    digest = hashlib.sha256(" ".join(tokens).encode()).digest()
    return hooks[digest[0] % len(hooks)]


def subtitles(path, words, length, title, name, notes=(), *, platform=None, campaign=None, gap="[Gameplay footage]"):
    lines = ["""[Script Info]
ScriptType: v4.00+
PlayResX: 1080
PlayResY: 1920
WrapStyle: 0
[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Caption,DejaVu Sans,68,&H0000E7FF,&H00FFFFFF,&H00090909,&H70000000,-1,0,0,0,100,100,0,0,1,5,2,5,86,86,0,1
Style: Hook,DejaVu Sans,64,&H00FFFFFF,&H00FFFFFF,&H00302014,&H80302014,-1,0,0,0,100,100,0,0,3,12,0,8,80,80,260,1
Style: Credit,DejaVu Sans,42,&H00FFFFFF,&H00FFFFFF,&H00202020,&H00202020,-1,0,0,0,100,100,0,0,3,5,0,1,58,96,165,1
[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text"""]
    def add(start, end, style, value):
        if end > start:
            lines.append(f"Dialogue: 0,{stamp(start)},{stamp(end)},{style},,0,0,0,,{value}")
    add(0, length, "Hook", safe(title)[:68])
    name = safe(name).strip().lstrip("@")
    if platform in ("Twitch", "Kick"):
        if not name:
            raise ValueError("A streamer handle is required for attribution")
        credit = f"Clip: @{name}"
    else:
        credit = "Credit: " + name
    if campaign:
        credit = (credit + " " + safe(campaign)).rstrip()
    add(0, length, "Credit", credit)
    for note in notes:
        add(max(0, float(note["start"])), min(length, float(note["end"])), "Credit",
            r"{\an5\pos(540,1470)}" + safe(note["text"])[:150])
    words = [item for item in words if valid_word(item)] if isinstance(words, (tuple, list)) else []
    words = sorted((max(0, s), min(length, e), w) for s, e, w in words if s < length and e > 0)
    pos = r"{\pos(540,1070)}"
    gap = r"{\fscx94\fscy94\t(0,90,\fscx100\fscy100)}" + gap
    cursor, previous_pair = 0, None
    for i, (start, end, _) in enumerate(words):
        start = max(start, cursor)
        if end <= start:
            continue
        # Hold the pair between adjacent words to avoid flashing a cue on tiny pauses.
        pause_text = previous_pair if previous_pair and start - cursor <= .35 else gap
        add(cursor, start, "Caption", pos + pause_text)
        # Reuse the preceding word for an odd final word rather than inventing a partner.
        pair = min(i // 2 * 2, max(0, len(words) - 2))
        previous_pair = " ".join(safe(w) for _, _, w in words[pair:pair+2])
        phrase = " ".join((r"{\1c&H00E7FF&\fscx94\fscy94\t(0,90,\fscx100\fscy100)}" if j == i
                           else r"{\1c&H00E7FF&\fscx100\fscy100}") + safe(w)
                          for j, (_, _, w) in enumerate(words[pair:pair+2], pair))
        add(start, end, "Caption", pos + phrase)
        cursor = end
    add(cursor, length, "Caption", pos + gap)
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def render_vertical_short(source, out, length, words, title, credit, notes=(), facecam=None, start=0, hook=None,
                          platform=None, campaign=None, gap=None):
    if not isfinite(length) or length <= 0:
        raise ValueError("Invalid segment duration")
    length = min(length, MAX_SEGMENT_SECONDS)
    ass = out.with_suffix(".ass")
    audio = any(s["codec_type"] == "audio" for s in probe(source)["streams"])
    subtitles(ass, words, length, curiosity_hook(title, hook), credit, notes, platform=platform,
              campaign=campaign, gap=gap if gap is not None else ("[Gameplay footage]" if audio else "[Silent footage]"))
    # Brief center punch-in on each cut, then settle back to uncropped gameplay.
    vf = ("[0:v]fps=30,setsar=1,split[back][front];"
          "[back]scale=270:480:force_original_aspect_ratio=increase,crop=270:480,"
          "boxblur=12:2,scale=1080:1920,eq=brightness=-0.12[bg];"
          "[front]scale=1080:960:force_original_aspect_ratio=decrease:force_divisible_by=2,"
          "pad=1080:960:(ow-iw)/2:(oh-ih)/2:color=black,"
          "zoompan=z='1+0.10*max(0,1-on/12)':x='iw/2-iw/zoom/2':"
          "y='ih/2-ih/zoom/2':d=1:s=1080x960:fps=30[fg];"
          f"[bg][fg]overlay=(W-w)/2:(H-h)/2,setsar=1,ass={ass.name}[v]")
    if facecam is not None:
        x, y, w, h = map(float, facecam)  # normalized left, top, width, height
        if not (all(isfinite(v) for v in (x, y, w, h)) and min(x, y) >= 0
                and min(w, h) > 0 and x+w <= 1 and y+h <= 1):
            raise ValueError("Invalid normalized facecam crop in editorial.json")
        vf = ("[0:v]fps=30,setsar=1,split[game_src][cam_src];"
              "[game_src]scale=1080:1150:force_original_aspect_ratio=increase,"
              "crop=1080:1150,setsar=1[game];"
              f"[cam_src]crop=iw*{w}:ih*{h}:iw*{x}:ih*{y},"
              "scale=1080:770:force_original_aspect_ratio=increase,crop=1080:770,setsar=1[cam];"
              f"[game][cam]vstack=inputs=2,ass={ass.name}[v]")
    cmd = ["ffmpeg", "-nostdin", "-loglevel", "error", "-y", "-filter_complex_threads", "2",
           "-ss", str(start), "-i", source.name]
    if not audio:
        cmd += ["-f", "lavfi", "-i", "anullsrc=r=44100:cl=stereo"]
    cmd += ["-filter_complex", vf, "-map", "[v]", "-map", "0:a:0" if audio else "1:a:0",
            "-af", "apad", "-t", f"{length:.3f}", "-c:v", "libx264", "-threads", "2",
            "-preset", "ultrafast", "-crf", "23", "-pix_fmt", "yuv420p", "-c:a", "aac",
            "-b:a", "128k", "-ar", "44100", "-ac", "2", "-movflags", "+faststart", out.name]
    run(cmd, out.parent)
    encoded = seconds(out)
    if platform in ("Twitch", "Kick") and encoded < MIN_SEGMENT_SECONDS:
        raise RuntimeError("Encoded clip shorter than 18 seconds")
    if encoded >= 44:
        raise RuntimeError("Encoded segment reached the 44-second limit")


render = render_vertical_short  # Existing sample scripts and external callers.


def join(parts, out):
    if not parts:
        raise ValueError("No rendered clips to concatenate")
    listing = out.parent / "parts.txt"
    listing.write_text("".join(f"file '{p.name}'\n" for p in parts))
    run(["ffmpeg", "-nostdin", "-loglevel", "error", "-y", "-f", "concat", "-safe", "1",
         "-i", listing.name, "-c", "copy", "-movflags", "+faststart", out.name], out.parent)
